import { useRef, useState, useCallback, Suspense } from "react";
import { AnimatePresence } from "framer-motion";
import Scene from "@/three/Scene";
import HudFrame from "@/components/hud/HudFrame";
import StationPanel from "@/components/hud/StationPanel";
import BootSequence from "@/components/hud/BootSequence";
import Reticle from "@/components/hud/Reticle";
import MusicPlayer from "@/components/hud/MusicPlayer";

export default function CommandCenter() {
  const controlsRef = useRef();
  const skip = typeof window !== "undefined" && window.location.search.includes("skipboot");
  const [booted, setBooted] = useState(skip);
  const [focus, setFocus] = useState(null);
  const [locked, setLocked] = useState(false);
  const [audioOn, setAudioOn] = useState(false);

  const handleSelect = useCallback((station) => setFocus(station), []);
  const handleReturn = useCallback(() => setFocus(null), []);
  const handleHover = useCallback((id) => setLocked(!!id), []);
  const handleEnter = useCallback(() => { setBooted(true); setAudioOn(true); }, []);
  const toggleAudio = useCallback(() => setAudioOn((a) => !a), []);

  return (
    <div data-testid="command-center-root" className={`relative w-screen h-screen overflow-hidden bg-[#03070A] ${booted ? "tactical-cursor" : ""}`}>
      <div className="fixed inset-0 z-0">
        <Suspense fallback={null}>
          <Scene focus={focus} onSelect={handleSelect} onHover={handleHover} controlsRef={controlsRef} />
        </Suspense>
      </div>

      {booted && (
        <>
          <HudFrame focus={focus} onSelect={handleSelect} onReturn={handleReturn} audioOn={audioOn} onToggleAudio={toggleAudio} />
          <StationPanel station={focus} onClose={handleReturn} />
        </>
      )}

      <div className="scanlines pointer-events-none fixed inset-0 z-[45] opacity-[0.12]" />
      <div className="vignette pointer-events-none fixed inset-0 z-[44]" />

      {booted && <Reticle locked={locked} />}

      <MusicPlayer playing={audioOn} />

      <AnimatePresence>
        {!booted && <BootSequence onComplete={handleEnter} />}
      </AnimatePresence>
    </div>
  );
}
