import { useEffect, useRef } from "react";

export default function Reticle({ locked }) {
  const ref = useRef();

  useEffect(() => {
    const move = (e) => {
      if (ref.current) {
        ref.current.style.transform = `translate(${e.clientX}px, ${e.clientY}px)`;
      }
    };
    window.addEventListener("pointermove", move);
    return () => window.removeEventListener("pointermove", move);
  }, []);

  const color = locked ? "#FFB800" : "#00F3FF";
  const size = locked ? 46 : 30;

  return (
    <div
      ref={ref}
      data-testid="tactical-reticle"
      className="fixed top-0 left-0 z-[60] pointer-events-none hidden md:block"
      style={{ willChange: "transform" }}
    >
      <div
        className="relative -translate-x-1/2 -translate-y-1/2"
        style={{ width: size, height: size, transition: "width 0.15s ease, height 0.15s ease" }}
      >
        {/* ring */}
        <div
          className="absolute inset-0 rounded-full"
          style={{ border: `1px solid ${color}`, opacity: 0.9, boxShadow: `0 0 8px ${color}` }}
        />
        {/* center dot */}
        <div
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full"
          style={{ width: 3, height: 3, background: color }}
        />
        {/* ticks */}
        {[["top", "-6px", "left", "50%"], ["bottom", "-6px", "left", "50%"], ["left", "-6px", "top", "50%"], ["right", "-6px", "top", "50%"]].map((p, i) => (
          <div key={i} className="absolute" style={{ [p[0]]: p[1], [p[2]]: p[3], width: p[0] === "left" || p[0] === "right" ? 5 : 1, height: p[0] === "left" || p[0] === "right" ? 1 : 5, background: color, transform: p[2] === "left" ? "translateX(-50%)" : "translateY(-50%)" }} />
        ))}
        {locked && (
          <div className="font-mono absolute -bottom-5 left-1/2 -translate-x-1/2" style={{ color, fontSize: 8, letterSpacing: "0.2em" }}>
            LOCK
          </div>
        )}
      </div>
    </div>
  );
}
