import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { Grid, Sparkles } from "@react-three/drei";
import * as THREE from "three";

function Pillar({ x, z }) {
  return (
    <group position={[x, 0, z]}>
      <mesh position={[0, 2, 0]} castShadow>
        <boxGeometry args={[0.6, 4, 0.6]} />
        <meshStandardMaterial color="#0a1418" metalness={0.6} roughness={0.4} />
      </mesh>
      <mesh position={[0, 2, 0.31]}>
        <planeGeometry args={[0.12, 3.4]} />
        <meshStandardMaterial color="#00F3FF" emissive="#00F3FF" emissiveIntensity={2.2} toneMapped={false} />
      </mesh>
    </group>
  );
}

function RadarSweep() {
  const ref = useRef();
  useFrame((_, d) => { if (ref.current) ref.current.rotation.z -= d * 0.5; });
  return (
    <mesh ref={ref} position={[0, 0.015, 0]} rotation={[-Math.PI / 2, 0, 0]}>
      <ringGeometry args={[0, 11, 48, 1, 0, Math.PI / 4]} />
      <meshBasicMaterial color="#00F3FF" transparent opacity={0.05} side={THREE.DoubleSide} blending={THREE.AdditiveBlending} />
    </mesh>
  );
}

export default function Hangar() {
  return (
    <group>
      <Grid
        args={[90, 90]}
        position={[0, -0.02, 0]}
        cellSize={1}
        cellThickness={0.6}
        cellColor="#0c3a45"
        sectionSize={5}
        sectionThickness={1.2}
        sectionColor="#0a5a6b"
        fadeDistance={55}
        fadeStrength={2.5}
        infiniteGrid
      />

      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.03, 0]} receiveShadow>
        <circleGeometry args={[30, 64]} />
        <meshStandardMaterial color="#04090c" metalness={0.4} roughness={0.7} />
      </mesh>

      <RadarSweep />

      <Pillar x={-14} z={-11} />
      <Pillar x={14} z={-11} />
      <Pillar x={-14} z={9} />
      <Pillar x={14} z={9} />

      <mesh position={[0, 3.5, -16]}>
        <planeGeometry args={[46, 0.08]} />
        <meshStandardMaterial color="#FFB800" emissive="#FFB800" emissiveIntensity={1.6} toneMapped={false} />
      </mesh>

      <Sparkles count={90} scale={[36, 9, 36]} size={2} speed={0.3} color="#00F3FF" opacity={0.4} position={[0, 3, 0]} />

      <fog attach="fog" args={["#03070A", 22, 55]} />
    </group>
  );
}
