import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { Float } from "@react-three/drei";
import * as THREE from "three";

function Trophy({ x, color }) {
  return (
    <group position={[x, 0, 0]}>
      {/* pedestal */}
      <mesh position={[0, 0.5, 0]}>
        <cylinderGeometry args={[0.55, 0.7, 1, 6]} />
        <meshStandardMaterial color="#0a161b" metalness={0.7} roughness={0.35} />
      </mesh>
      <mesh position={[0, 1.02, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[0.4, 0.52, 6]} />
        <meshStandardMaterial color={color} emissive={color} emissiveIntensity={2.2} toneMapped={false} side={THREE.DoubleSide} />
      </mesh>
      {/* floating medal */}
      <Float speed={2.2} rotationIntensity={0.8} floatIntensity={0.6}>
        <group position={[0, 1.9, 0]}>
          <mesh rotation={[Math.PI / 2, 0, 0]}>
            <cylinderGeometry args={[0.34, 0.34, 0.07, 6]} />
            <meshStandardMaterial color={color} emissive={color} emissiveIntensity={1.8} metalness={0.6} roughness={0.3} toneMapped={false} />
          </mesh>
          <mesh>
            <icosahedronGeometry args={[0.16, 0]} />
            <meshStandardMaterial color="#03070A" emissive={color} emissiveIntensity={0.6} />
          </mesh>
          <pointLight color={color} intensity={2} distance={4} />
        </group>
      </Float>
    </group>
  );
}

export default function ArmoryModel({ active }) {
  const holo = useRef();
  const ringA = useRef();
  const ringB = useRef();
  useFrame((_, d) => {
    const s = active ? 2 : 1;
    if (holo.current) holo.current.rotation.y += d * 0.5 * s;
    if (ringA.current) ringA.current.rotation.x += d * 0.8 * s;
    if (ringB.current) ringB.current.rotation.z += d * 0.6 * s;
  });

  return (
    <group>
      {/* Base slab */}
      <mesh position={[0, 0.1, 0]}>
        <boxGeometry args={[4.4, 0.2, 1.8]} />
        <meshStandardMaterial color="#0a161b" metalness={0.6} roughness={0.4} />
      </mesh>

      {/* Two award trophies */}
      <Trophy x={-1.5} color="#FFB800" />
      <Trophy x={1.5} color="#00F3FF" />

      {/* Central FlightOps holographic display */}
      <Float speed={1.6} floatIntensity={0.4} rotationIntensity={0}>
        <group position={[0, 2.7, 0]}>
          {/* container stack (digital twin) */}
          <group ref={holo}>
            {[-0.3, 0, 0.3].map((y, i) => (
              <mesh key={i} position={[0, y, 0]}>
                <boxGeometry args={[0.8 - i * 0.05, 0.22, 0.8 - i * 0.05]} />
                <meshBasicMaterial color="#00F3FF" wireframe transparent opacity={0.7} blending={THREE.AdditiveBlending} />
              </mesh>
            ))}
          </group>
          <mesh ref={ringA} rotation={[Math.PI / 2, 0, 0]}>
            <torusGeometry args={[1.1, 0.015, 8, 64]} />
            <meshBasicMaterial color="#00F3FF" transparent opacity={0.8} blending={THREE.AdditiveBlending} />
          </mesh>
          <mesh ref={ringB}>
            <torusGeometry args={[0.85, 0.015, 8, 64]} />
            <meshBasicMaterial color="#FFB800" transparent opacity={0.7} blending={THREE.AdditiveBlending} />
          </mesh>
          <pointLight color="#00F3FF" intensity={4} distance={6} />
        </group>
      </Float>

      {/* projector beam */}
      <mesh position={[0, 1.5, 0]}>
        <coneGeometry args={[1, 1.6, 6, 1, true]} />
        <meshBasicMaterial color="#00F3FF" transparent opacity={0.05} blending={THREE.AdditiveBlending} side={THREE.DoubleSide} />
      </mesh>
    </group>
  );
}
