import { useRef } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";

const OVERVIEW = { pos: [0, 11, 15], look: [0, 1, 0] };

export default function CameraRig({ focus, controlsRef }) {
  const { camera } = useThree();
  const targetPos = useRef(new THREE.Vector3());
  const targetLook = useRef(new THREE.Vector3());

  useFrame(() => {
    const controls = controlsRef.current;
    if (!controls) return;
    const dest = focus ? focus.camera : OVERVIEW;
    targetPos.current.set(...dest.pos);
    targetLook.current.set(...dest.look);

    if (focus) {
      controls.enabled = false;
      camera.position.lerp(targetPos.current, 0.06);
      controls.target.lerp(targetLook.current, 0.06);
      controls.update();
    } else if (!controls.enabled) {
      // returning to overview, then hand control back to the user
      camera.position.lerp(targetPos.current, 0.06);
      controls.target.lerp(targetLook.current, 0.06);
      controls.update();
      if (camera.position.distanceTo(targetPos.current) < 0.5) {
        controls.enabled = true;
      }
    }
  });

  return null;
}
