import { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import { Float } from "@react-three/drei";
import * as THREE from "three";

function Rack({ x }) {
  const lights = useMemo(
    () => Array.from({ length: 6 }, (_, i) => ({ y: 0.4 + i * 0.42, on: Math.random() > 0.4 })),
    []
  );
  return (
    <group position={[x, 0, 0]}>
      <mesh position={[0, 1.5, 0]}>
        <boxGeometry args={[1, 3, 0.9]} />
        <meshStandardMaterial color="#0a161b" metalness={0.75} roughness={0.3} />
      </mesh>
      {lights.map((l, i) => (
        <mesh key={i} position={[0.2, l.y, 0.46]}>
          <planeGeometry args={[0.5, 0.14]} />
          <meshStandardMaterial
            color={l.on ? "#00F3FF" : "#0f3d45"}
            emissive={l.on ? "#00F3FF" : "#0a2a30"}
            emissiveIntensity={l.on ? 2.2 : 0.3}
            toneMapped={false}
          />
        </mesh>
      ))}
    </group>
  );
}

export default function NeuralModel() {
  const brain = useRef();
  useFrame((_, d) => {
    if (brain.current) {
      brain.current.rotation.y += d * 0.5;
      brain.current.rotation.x += d * 0.15;
    }
  });

  return (
    <group>
      {/* Base slab */}
      <mesh position={[0, 0.1, 0]}>
        <boxGeometry args={[4.2, 0.2, 1.6]} />
        <meshStandardMaterial color="#0a161b" metalness={0.6} roughness={0.4} />
      </mesh>

      {/* Server racks */}
      <Rack x={-1.3} />
      <Rack x={0} />
      <Rack x={1.3} />

      {/* Floating neural brain */}
      <Float speed={2} rotationIntensity={0} floatIntensity={0.5}>
        <group position={[0, 3.9, 0]}>
          <mesh ref={brain}>
            <icosahedronGeometry args={[0.8, 1]} />
            <meshBasicMaterial color="#00F3FF" wireframe transparent opacity={0.7} blending={THREE.AdditiveBlending} />
          </mesh>
          <mesh>
            <icosahedronGeometry args={[0.5, 0]} />
            <meshStandardMaterial color="#00F3FF" emissive="#00F3FF" emissiveIntensity={1.4} transparent opacity={0.4} toneMapped={false} />
          </mesh>
          <pointLight color="#00F3FF" intensity={4} distance={6} />
        </group>
      </Float>

      {/* Data beam linking racks to brain */}
      <mesh position={[0, 2.4, 0]}>
        <cylinderGeometry args={[0.03, 0.03, 2, 8]} />
        <meshBasicMaterial color="#00F3FF" transparent opacity={0.5} blending={THREE.AdditiveBlending} />
      </mesh>
    </group>
  );
}
