import { Float } from "@react-three/drei";
import * as THREE from "three";

function Medal({ x, z, color }) {
  return (
    <Float speed={2.4} rotationIntensity={0.6} floatIntensity={0.7}>
      <group position={[x, 1.4, z]}>
        <mesh rotation={[Math.PI / 2, 0, 0]}>
          <cylinderGeometry args={[0.22, 0.22, 0.05, 6]} />
          <meshStandardMaterial color={color} emissive={color} emissiveIntensity={1.6} metalness={0.6} roughness={0.3} toneMapped={false} />
        </mesh>
        <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, 0, 0.03]}>
          <ringGeometry args={[0.1, 0.16, 6]} />
          <meshBasicMaterial color="#03070A" side={THREE.DoubleSide} />
        </mesh>
      </group>
    </Float>
  );
}

export default function BriefingModel() {
  return (
    <group>
      {/* Hex map table */}
      <mesh position={[0, 0.5, 0]}>
        <cylinderGeometry args={[2.4, 2.7, 1, 6]} />
        <meshStandardMaterial color="#0a161b" metalness={0.6} roughness={0.4} />
      </mesh>

      {/* Glowing tactical map surface */}
      <mesh position={[0, 1.02, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <circleGeometry args={[2.0, 6]} />
        <meshStandardMaterial color="#08343d" emissive="#FFB800" emissiveIntensity={0.28} toneMapped={false} />
      </mesh>
      {/* Map grid lines */}
      <gridHelper args={[3.2, 6, "#FFB800", "#0f5a66"]} position={[0, 1.03, 0]} />
      <mesh position={[0, 1.04, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.5, 1.6, 48]} />
        <meshBasicMaterial color="#FFB800" transparent opacity={0.6} side={THREE.DoubleSide} />
      </mesh>

      {/* Floating mission patches / medals */}
      <Medal x={-1} z={-0.6} color="#FFB800" />
      <Medal x={0.9} z={0.5} color="#00F3FF" />
      <Medal x={0.2} z={-1} color="#FFB800" />
      <Medal x={-0.7} z={0.8} color="#00F3FF" />

      {/* Projection beam */}
      <mesh position={[0, 1.8, 0]}>
        <coneGeometry args={[1.6, 1.4, 6, 1, true]} />
        <meshBasicMaterial color="#FFB800" transparent opacity={0.05} blending={THREE.AdditiveBlending} side={THREE.DoubleSide} />
      </mesh>
      <pointLight color="#FFB800" intensity={3} distance={7} position={[0, 2, 0]} />
    </group>
  );
}
