import { useRef, Suspense } from "react";
import { useFrame } from "@react-three/fiber";
import { Float } from "@react-three/drei";
import * as THREE from "three";
import Phone from "@/three/Phone";

export default function CommandTable() {
  const ring = useRef();
  const ring2 = useRef();

  useFrame((_, delta) => {
    if (ring.current) ring.current.rotation.z += delta * 0.35;
    if (ring2.current) ring2.current.rotation.z -= delta * 0.25;
  });

  return (
    <group position={[0, 0, 0]}>
      {/* Hex table base */}
      <mesh position={[0, 0.5, 0]}>
        <cylinderGeometry args={[2.6, 3, 1, 6]} />
        <meshStandardMaterial color="#0a1a20" metalness={0.7} roughness={0.35} />
      </mesh>
      {/* Glowing rim */}
      <mesh position={[0, 1.02, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[2.3, 2.55, 6]} />
        <meshStandardMaterial color="#00F3FF" emissive="#00F3FF" emissiveIntensity={2.5} toneMapped={false} side={THREE.DoubleSide} />
      </mesh>

      {/* Holographic CoreLedger phone centerpiece */}
      <Float speed={2} rotationIntensity={0} floatIntensity={0.6}>
        <group position={[0, 2.6, 0]}>
          <Suspense fallback={null}>
            <Phone />
          </Suspense>
          <mesh ref={ring} rotation={[Math.PI / 2, 0.3, 0]}>
            <torusGeometry args={[1.6, 0.02, 8, 64]} />
            <meshBasicMaterial color="#00F3FF" transparent opacity={0.8} blending={THREE.AdditiveBlending} />
          </mesh>
          <mesh ref={ring2} rotation={[Math.PI / 2.4, -0.3, 0]}>
            <torusGeometry args={[1.9, 0.015, 8, 64]} />
            <meshBasicMaterial color="#FFB800" transparent opacity={0.55} blending={THREE.AdditiveBlending} />
          </mesh>
        </group>
      </Float>

      {/* Projection beam base */}
      <mesh position={[0, 1.6, 0]}>
        <coneGeometry args={[1.4, 1.2, 6, 1, true]} />
        <meshBasicMaterial color="#00F3FF" transparent opacity={0.06} blending={THREE.AdditiveBlending} side={THREE.DoubleSide} />
      </mesh>
    </group>
  );
}
