import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";

const LINES = [
  "> INITIALIZING TACTICAL INTERFACE...",
  "> VERIFYING COMMANDER STATUS :: MISSION-READY ... OK",
  "> LOADING HANGAR BAY GEOMETRY ............... OK",
  "> CALIBRATING HOLOGRAPHIC PROJECTORS ........ OK",
  "> LINKING STATIONS [ 01 · 02 · 03 ] ......... OK",
  "> NEURAL MESH SYNC .......................... OK",
  "> WELCOME, COMMANDER.",
];

export default function BootSequence({ onComplete }) {
  const [visible, setVisible] = useState(0);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    if (visible < LINES.length) {
      const t = setTimeout(() => setVisible((v) => v + 1), visible === 0 ? 350 : 260);
      return () => clearTimeout(t);
    }
    const t = setTimeout(() => setReady(true), 350);
    return () => clearTimeout(t);
  }, [visible]);

  return (
    <div data-testid="boot-sequence" className="fixed inset-0 z-[70] bg-[#03070A] flex items-center justify-center p-6">
      <div className="w-full max-w-2xl">
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="hud-panel p-6 md:p-10"
        >
          <div className="hud-label mb-6 flex items-center justify-between">
            <span className="hud-text-cyan">SYSTEM BOOT</span>
            <span className="text-[var(--text-muted)]">v2.7.2 · SECURE</span>
          </div>

          <div className="font-mono text-sm space-y-2 min-h-[220px]">
            {LINES.slice(0, visible).map((line, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
                className={i === LINES.length - 1 ? "hud-text-cyan text-lg tracking-widest" : "text-[var(--text-secondary)]"}
              >
                {line}
                {i === visible - 1 && <span className="blink">_</span>}
              </motion.div>
            ))}
          </div>

          <AnimatePresence>
            {ready && (
              <motion.button
                data-testid="enter-command-center-btn"
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                onClick={onComplete}
                className="mt-8 w-full py-4 font-mono tracking-[0.35em] uppercase text-[#03070A] font-bold hover:brightness-110"
                style={{ background: "var(--cyan)", clipPath: "polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px))", boxShadow: "0 0 30px var(--cyan-glow)" }}
              >
                ▸ Enter Command Center
              </motion.button>
            )}
          </AnimatePresence>
        </motion.div>
      </div>
    </div>
  );
}
