import { useRef, useState } from "react";
import { useFrame } from "@react-three/fiber";
import { useTexture, Html } from "@react-three/drei";
import * as THREE from "three";

const PLAY_URL = "https://play.google.com/store/apps/details?id=dev.naci.subtrack";

export default function Phone() {
  const group = useRef();
  const [hovered, setHovered] = useState(false);
  const tex = useTexture("/logos/coreledger.png");

  useFrame((state) => {
    if (group.current) {
      group.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.5) * 0.5;
    }
  });

  const openStore = (e) => {
    e.stopPropagation();
    window.open(PLAY_URL, "_blank", "noopener");
  };

  return (
    <group ref={group}>
      {/* glow halo behind the phone */}
      <mesh position={[0, 0, -0.08]}>
        <planeGeometry args={[1.5, 2.5]} />
        <meshBasicMaterial color="#00F3FF" transparent opacity={hovered ? 0.22 : 0.12} blending={THREE.AdditiveBlending} />
      </mesh>

      {/* phone body */}
      <mesh
        onClick={openStore}
        onPointerOver={(e) => { e.stopPropagation(); setHovered(true); }}
        onPointerOut={(e) => { e.stopPropagation(); setHovered(false); }}
      >
        <boxGeometry args={[0.98, 1.98, 0.09]} />
        <meshStandardMaterial color="#0a1418" metalness={0.8} roughness={0.25} emissive="#00F3FF" emissiveIntensity={hovered ? 0.25 : 0.08} />
      </mesh>

      {/* screen background */}
      <mesh position={[0, 0, 0.048]}>
        <planeGeometry args={[0.86, 1.78]} />
        <meshBasicMaterial color="#04141c" toneMapped={false} />
      </mesh>

      {/* app logo on screen */}
      <mesh position={[0, 0.12, 0.05]}>
        <planeGeometry args={[0.62, 0.62]} />
        <meshBasicMaterial map={tex} transparent toneMapped={false} />
      </mesh>

      {/* app name on screen */}
      <Html position={[0, -0.5, 0.06]} center distanceFactor={6} pointerEvents="none" zIndexRange={[3, 0]}>
        <div style={{ textAlign: "center", whiteSpace: "nowrap", pointerEvents: "none" }}>
          <div style={{ fontFamily: "'Rajdhani',sans-serif", fontWeight: 700, letterSpacing: "0.14em", fontSize: 16, color: "#E0F7FA", textShadow: "0 0 8px #00F3FF" }}>CORELEDGER</div>
          <div style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 8, letterSpacing: "0.2em", color: "#7AA2A8" }}>FINANCE · GOOGLE PLAY </div>
        </div>
      </Html>

      {/* floating call-to-action tag */}
      <Html position={[0, 1.35, 0]} center distanceFactor={8} pointerEvents="none" zIndexRange={[4, 0]}>
        <div
          className={hovered ? "blink" : ""}
          style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 10, letterSpacing: "0.25em", color: "#00F3FF", textShadow: "0 0 8px #00F3FF", whiteSpace: "nowrap", pointerEvents: "none" }}
        >
          ◉ TAP TO LAUNCH
        </div>
      </Html>

      <pointLight color="#00F3FF" intensity={hovered ? 6 : 3} distance={6} />
    </group>
  );
}
