import { useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls, Html } from "@react-three/drei";
import * as THREE from "three";

import Hangar from "@/three/Hangar";
import CommandTable from "@/three/CommandTable";
import DroneModel from "@/three/DroneModel";
import NeuralModel from "@/three/NeuralModel";
import BriefingModel from "@/three/BriefingModel";
import ArmoryModel from "@/three/ArmoryModel";
import CameraRig from "@/three/CameraRig";
import { STATIONS } from "@/data/stations";

const MODELS = {
  launchpad: DroneModel,
  neuralcore: NeuralModel,
  briefing: BriefingModel,
  armory: ArmoryModel,
};

function Hotspot({ color }) {
  const ring = useRef();
  useFrame((state) => {
    if (ring.current) {
      const s = 1 + Math.sin(state.clock.elapsedTime * 2) * 0.12;
      ring.current.scale.set(s, s, s);
    }
  });
  return (
    <mesh ref={ring} position={[0, 0.06, 0]} rotation={[-Math.PI / 2, 0, 0]}>
      <ringGeometry args={[2.5, 2.7, 48]} />
      <meshBasicMaterial color={color} transparent opacity={0.5} side={THREE.DoubleSide} />
    </mesh>
  );
}

function Selectable({ station, activeId, onSelect, onHover, children }) {
  const inner = useRef();
  const [hovered, setHovered] = useState(false);
  const tmp = useRef(new THREE.Vector3());
  const isActive = activeId === station.id;

  useFrame(() => {
    if (!inner.current) return;
    const t = hovered && !isActive ? 1.05 : 1;
    tmp.current.set(t, t, t);
    inner.current.scale.lerp(tmp.current, 0.12);
  });

  return (
    <group
      position={station.position}
      onPointerOver={(e) => { e.stopPropagation(); setHovered(true); onHover(station.id); }}
      onPointerOut={(e) => { e.stopPropagation(); setHovered(false); onHover(null); }}
      onClick={(e) => { e.stopPropagation(); onSelect(station); }}
    >
      <group ref={inner}>{children}</group>
      <Hotspot color={station.color} />
      {!isActive && (
        <Html position={[0, station.labelY ?? 4.6, 0]} center distanceFactor={15} pointerEvents="none" zIndexRange={[5, 0]}>
          <div style={{ pointerEvents: "none", textAlign: "center", whiteSpace: "nowrap", transform: "translateY(-10px)" }}>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, letterSpacing: "0.3em", color: station.color, opacity: hovered ? 1 : 0.6 }}>
              [{station.index}]
            </div>
            <div style={{ fontFamily: "'Rajdhani', sans-serif", fontWeight: 700, fontSize: 22, letterSpacing: "0.12em", textTransform: "uppercase", color: "#E0F7FA", textShadow: `0 0 10px ${station.color}` }}>
              {station.name}
            </div>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 9, letterSpacing: "0.25em", color: station.color, opacity: hovered ? 1 : 0 }} className={hovered ? "blink" : ""}>
              ◉ CLICK TO ENGAGE
            </div>
          </div>
        </Html>
      )}
    </group>
  );
}

export default function Scene({ focus, onSelect, onHover, controlsRef }) {
  return (
    <Canvas
      shadows
      camera={{ position: [0, 11, 15], fov: 52 }}
      gl={{ antialias: true, toneMapping: THREE.ACESFilmicToneMapping }}
      dpr={[1, 1.8]}
    >
      <color attach="background" args={["#03070A"]} />

      <ambientLight intensity={0.45} />
      <hemisphereLight args={["#0a2a33", "#03070A", 0.6]} />
      <directionalLight position={[6, 12, 6]} intensity={0.9} color="#bfefff" castShadow />
      <pointLight position={[-12, 5, -8]} intensity={45} color="#00F3FF" distance={34} />
      <pointLight position={[12, 5, -8]} intensity={35} color="#00F3FF" distance={34} />
      <pointLight position={[0, 4, 11]} intensity={28} color="#FFB800" distance={30} />
      <pointLight position={[0, 4, -11]} intensity={22} color="#FFB800" distance={30} />

      <Hangar />
      <CommandTable />

      {STATIONS.map((st) => {
        const Model = MODELS[st.id];
        return (
          <Selectable key={st.id} station={st} activeId={focus?.id} onSelect={onSelect} onHover={onHover}>
            <Model active={focus?.id === st.id} />
          </Selectable>
        );
      })}

      <CameraRig focus={focus} controlsRef={controlsRef} />
      <OrbitControls
        ref={controlsRef}
        enablePan
        enableDamping
        dampingFactor={0.08}
        minDistance={5}
        maxDistance={34}
        maxPolarAngle={Math.PI / 2.15}
        target={[0, 1, 0]}
      />
    </Canvas>
  );
}
