import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

function Rotor({ x, z, active }) {
  const prop = useRef();
  useFrame((_, d) => { if (prop.current) prop.current.rotation.y += d * (active ? 45 : 6); });
  return (
    <group position={[x, 0.15, z]}>
      <mesh>
        <cylinderGeometry args={[0.32, 0.32, 0.12, 24]} />
        <meshStandardMaterial color="#0c1c22" metalness={0.7} roughness={0.3} />
      </mesh>
      <mesh position={[0, 0.07, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[0.28, 0.34, 24]} />
        <meshStandardMaterial color="#00F3FF" emissive="#00F3FF" emissiveIntensity={active ? 3 : 2} toneMapped={false} side={THREE.DoubleSide} />
      </mesh>
      <mesh ref={prop} position={[0, 0.14, 0]}>
        <boxGeometry args={[0.56, 0.02, 0.06]} />
        <meshStandardMaterial color="#7AA2A8" transparent opacity={0.5} />
      </mesh>
    </group>
  );
}

// Holographic detection targets that appear during a scan
function Detection({ intensity }) {
  const sweep = useRef();
  useFrame((state) => {
    if (sweep.current) sweep.current.position.y = 0.3 + ((state.clock.elapsedTime * 0.8) % 1.4);
  });
  if (intensity < 0.02) return null;
  const boxes = [[1.2, 0.4], [-1.1, -0.9], [0.2, 1.3]];
  return (
    <group>
      {/* downward scan cone */}
      <mesh position={[0, 0.9, 0]}>
        <coneGeometry args={[1.9, 1.8, 24, 1, true]} />
        <meshBasicMaterial color="#00F3FF" transparent opacity={0.06 * intensity} blending={THREE.AdditiveBlending} side={THREE.DoubleSide} />
      </mesh>
      {/* rising scan plane */}
      <mesh ref={sweep} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[0.2, 1.9, 40]} />
        <meshBasicMaterial color="#00F3FF" transparent opacity={0.18 * intensity} side={THREE.DoubleSide} blending={THREE.AdditiveBlending} />
      </mesh>
      {/* target lock boxes on the pad */}
      {boxes.map(([x, z], i) => (
        <group key={i} position={[x, 0.35, z]}>
          <mesh>
            <boxGeometry args={[0.4, 0.4, 0.4]} />
            <meshBasicMaterial color="#FFB800" wireframe transparent opacity={0.9 * intensity} />
          </mesh>
        </group>
      ))}
    </group>
  );
}

export default function DroneModel({ active }) {
  const drone = useRef();
  const scan = useRef(0);
  const tmp = useRef(0);

  useFrame((state, d) => {
    if (!drone.current) return;
    // fly up when active, land when idle
    const targetY = active ? 2.3 : 0.75;
    const bob = active ? Math.sin(state.clock.elapsedTime * 2) * 0.08 : 0;
    drone.current.position.y = THREE.MathUtils.lerp(drone.current.position.y, targetY + bob, 0.05);
    // gentle yaw while scanning
    drone.current.rotation.y = THREE.MathUtils.lerp(drone.current.rotation.y, active ? Math.sin(state.clock.elapsedTime * 0.6) * 0.5 : 0, 0.04);
    // scan intensity
    tmp.current = THREE.MathUtils.lerp(tmp.current, active ? 1 : 0, 0.08);
    scan.current = tmp.current;
  });

  return (
    <group>
      {/* Launchpad */}
      <mesh position={[0, 0.1, 0]}>
        <cylinderGeometry args={[2.1, 2.3, 0.2, 32]} />
        <meshStandardMaterial color="#0a161b" metalness={0.6} roughness={0.4} />
      </mesh>
      <mesh position={[0, 0.21, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.6, 1.9, 48]} />
        <meshStandardMaterial color="#00F3FF" emissive="#00F3FF" emissiveIntensity={active ? 2.6 : 1.6} toneMapped={false} side={THREE.DoubleSide} />
      </mesh>

      {/* Drone body (lifts on activation) */}
      <group ref={drone} position={[0, 0.75, 0]}>
        <mesh rotation={[Math.PI / 2, 0, 0]}>
          <capsuleGeometry args={[0.35, 0.9, 8, 16]} />
          <meshStandardMaterial color="#13272e" metalness={0.8} roughness={0.25} />
        </mesh>
        <mesh position={[0, 0.18, 0.35]}>
          <sphereGeometry args={[0.28, 16, 16, 0, Math.PI * 2, 0, Math.PI / 2]} />
          <meshStandardMaterial color="#00F3FF" emissive="#00F3FF" emissiveIntensity={0.6} metalness={0.3} roughness={0.1} transparent opacity={0.85} />
        </mesh>
        {[45, 135, 225, 315].map((deg) => {
          const r = (deg * Math.PI) / 180;
          return (
            <mesh key={deg} rotation={[0, -r, 0]}>
              <boxGeometry args={[1.5, 0.06, 0.1]} />
              <meshStandardMaterial color="#0c1c22" metalness={0.7} roughness={0.3} />
            </mesh>
          );
        })}
        {[[0.53, 0.53], [-0.53, 0.53], [0.53, -0.53], [-0.53, -0.53]].map(([x, z], i) => (
          <Rotor key={i} x={x} z={z} active={active} />
        ))}
        <mesh position={[0, -0.35, 0]}>
          <coneGeometry args={[0.3, 0.7, 12, 1, true]} />
          <meshBasicMaterial color="#FFB800" transparent opacity={active ? 0.5 : 0.25} blending={THREE.AdditiveBlending} side={THREE.DoubleSide} />
        </mesh>
        <pointLight color="#00F3FF" intensity={active ? 5 : 3} distance={5} />
      </group>

      <Detection intensity={active ? 1 : 0} />
    </group>
  );
}
