import { useEffect, useRef } from "react";

export default function MusicPlayer({ playing }) {
  const audioRef = useRef(null);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    // Set volume to 30% to match your previous YouTube configuration
    audio.volume = 0.3;

    if (playing) {
      // The .catch() prevents the app from crashing if the browser blocks auto-play
      audio.play().catch((err) => {
        console.log("Audio play blocked by browser:", err);
      });
    } else {
      audio.pause();
    }
  }, [playing]);

  return (
    <audio
      ref={audioRef}
      src={`${process.env.PUBLIC_URL}/onlap.mp3`}
      loop
      style={{ display: "none" }}
    />
  );
}